(async()=>{
const profile='${@params/profile}';
const call=async(method,body)=>{const r=await fetch('/vrooli.notification_hub.v1.recipients.RecipientsService/'+method,{method:'POST',headers:{'content-type':'application/json','X-Vrooli-Test-Mode':'1','X-Vrooli-Browser-Session':'1'},credentials:'same-origin',body:JSON.stringify(body)});if(!r.ok)throw new Error(method+' failed '+r.status);return r.json();};
const me=await call('GetRecipient',{});
if(me.subject!=='e1-fixture@notification-hub.invalid')throw new Error('refusing to touch anything: this is not the routed test owner ('+me.subject+')');
if(profile==='keep')return {profile,routedTestOwner:true};
const {devices=[]}=await call('ListDevices',{});
for(const d of devices)await call('RemoveDevice',{id:d.id});
const {windows=[]}=await call('ListQuietWindows',{});
for(const w of windows)await call('DeleteQuietWindow',{id:w.id});
await call('SetEscalationChain',{channels:[]});
if(profile==='reach'){
await call('UpsertDevice',{id:'settings-test-laptop',name:'Work laptop',machineId:'settings-test-machine'});
await call('UpsertChannelAddress',{id:'settings-test-laptop-email',deviceId:'settings-test-laptop',channel:'email',address:'owner@example.test',approvedLabels:['public','private']});
await call('UpsertChannelAddress',{id:'settings-test-laptop-web-push',deviceId:'settings-test-laptop',channel:'web_push',address:'https://push.example.test/work-laptop',approvedLabels:['public','private']});
await call('UpsertDevice',{id:'settings-test-tablet',name:'Spare tablet',machineId:''});
await call('UpsertChannelAddress',{id:'settings-test-tablet-web-push',deviceId:'settings-test-tablet',channel:'web_push',address:'https://push.example.test/spare-tablet',approvedLabels:['public']});
await call('SetEscalationChain',{channels:['email','web_push']});
}
return {profile};
})()
